  Lemma umap_xfer_ins : forall (NS : Z) {V : Type} (lv lv1 B R : list (Z * Z)) (p : Z) (kv : Z * V) (ents ents' : list (Z * (Z * V))) (inserted : bool),
    NoDup (map fst lv) ->
    Permutation lv (B ++ map (fun e => (fst e, NS)) ents ++ R) ->
    (inserted = false -> map fst ents' = map fst ents) ->
    (inserted = true -> Permutation ents' ((p, kv) :: ents)) ->
    lapply lv (if inserted then [LAdd p NS] else []) lv1 ->
    Permutation lv1 (B ++ map (fun e => (fst e, NS)) ents' ++ R) /\ NoDup (map fst lv1).
