  Definition set_m2 (c : pmc) (m : Z * Z * list (Z * (Z * (Z * Z * Z)))) : pmc :=
    {| c_widx := c_widx c; c_icount := c_icount c; c_endian := c_endian c; c_reqconv := c_reqconv c;
