  Lemma pm_h5 : forall (w : pmw MI ST) c0 K (fx : FPState) A M model c R (key : Z) (val : Z * Z * Z) (v2 : Z),
    PMS w c0 K -> frm_zero (@fp_csr fx) ->
    PMX w A M model c -> c_tr c = [] -> pm_bud (w_n w) c ->
    PmLoopS1.nodes c + 2 <= c_widx c + 3 -> PmLoopS1.macct c -> 2 * Zlen (t3c (c_m2 c)) + 2 <= c_widx c ->
    oregs w R -> getr R 21%bv = Z_to_bv 64 (t3a val) -> getr R 18%bv = Z_to_bv 64 v2 -> getr R 27%bv = Z_to_bv 64 (t3c val) ->
    0 <= t3a val < 2 ^ 32 -> 0 <= t3b val < 2 ^ 32 -> 0 <= t3c val < 2 ^ 32 -> 0 <= v2 < 2 ^ 64 -> v2 mod 2 ^ 32 = t3b val ->
